//! Wolfram golden replay: compact FW-H single-element kernel.
//!
//! The fixture (`fixtures/wolfram-golden-v1.json`, generated by
//! `fixtures/fwh_golden.wls` under Wolfram Engine 15.0.0) evaluates the
//! monopole and dipole pressure of one surface element at exact 3-4-5
//! geometry with an independent complex-exponential formulation. The replay
//! pins the retarded phase sign, the 4 Pi normalization, the normal
//! projection, and the peak-phasor multiply-by-I convention of the
//! production observer path.

use serde::Deserialize;
use sonium_sim_propellers::blade3d::Point3;
use sonium_sim_propellers::fwh_reference::{FwhOptions, FwhSurfaceElement, evaluate_fwh_reference};
use std::collections::HashMap;

const FIXTURE: &str = include_str!("../fixtures/wolfram-golden-v1.json");

#[derive(Debug, Deserialize)]
struct Entry {
    value: String,
    exact: String,
}

#[derive(Debug, Deserialize)]
struct Meta {
    engine: String,
    protocol: String,
}

#[derive(Debug, Deserialize)]
struct Fixture {
    meta: Meta,
    values: HashMap<String, Entry>,
}

fn parse_fixture() -> Fixture {
    let fixture: Fixture = serde_json::from_str(FIXTURE).expect("valid Wolfram FWH fixture");
    assert!(
        fixture.meta.engine.contains("Wolfram Engine"),
        "fixture must record its Wolfram provenance"
    );
    assert_eq!(fixture.meta.protocol, "audit-oracle-hermetic-v1");
    fixture
}

fn golden(fixture: &Fixture, name: &str) -> f64 {
    fixture.values[name]
        .value
        .parse()
        .expect("golden is a decimal")
}

#[test]
fn single_element_monopole_dipole_match_wolfram() {
    let fixture = parse_fixture();
    assert!(
        fixture.values["cos_theta"].exact.contains("-3/5"),
        "geometry golden must document the 3-4-5 design"
    );
    let options = FwhOptions {
        frequency_hz: 100.0,
        density_kg_m3: 1.2,
        sound_speed_m_s: 343.0,
        observer_position: Point3 {
            x: 0.0,
            y: 0.0,
            z: 0.0,
        },
        minimum_observer_distance_m: 1.0,
        maximum_elements: 16,
    };
    let element = FwhSurfaceElement {
        position: Point3 {
            x: 3.0,
            y: 4.0,
            z: 0.0,
        },
        normal: Point3 {
            x: 1.0,
            y: 0.0,
            z: 0.0,
        },
        area_m2: 0.5,
        pressure_real_pa: 2.0,
        pressure_imaginary_pa: 0.0,
        normal_velocity_real_m_s: 0.01,
        normal_velocity_imaginary_m_s: 0.02,
    };
    let result =
        evaluate_fwh_reference(&[element], options).expect("single-element FW-H input is valid");
    assert_eq!(result.total_surface_area_m2, 0.5);
    assert_eq!(result.minimum_observer_distance_m, 5.0);
    assert_eq!(result.maximum_observer_distance_m, 5.0);

    for (name, actual) in [
        ("mono_re", result.monopole_pressure_pa.real_pa),
        ("mono_im", result.monopole_pressure_pa.imaginary_pa),
        ("di_re", result.dipole_pressure_pa.real_pa),
        ("di_im", result.dipole_pressure_pa.imaginary_pa),
    ] {
        let expected = golden(&fixture, name);
        let scale = actual.abs().max(expected.abs()).max(1e-30);
        assert!(
            (actual - expected).abs() / scale < 1e-12,
            "{name}: Rust {actual} vs Wolfram {expected}"
        );
    }
    // Coherent total is the complex sum, not a re-derived quantity.
    assert_eq!(
        result.total_pressure_pa.real_pa,
        result.monopole_pressure_pa.real_pa + result.dipole_pressure_pa.real_pa
    );
    assert_eq!(
        result.total_pressure_pa.imaginary_pa,
        result.monopole_pressure_pa.imaginary_pa + result.dipole_pressure_pa.imaginary_pa
    );
}
